export function nativeCompanyOperationsSeedPlan(){
 const rows=[],insert=(table,row)=>rows.push({table,row}),at=new Date('2026-11-08T12:00:00Z'),privateText='OPERATIONS88_PRIVATE_CANARY';
 for(const [id,companyId,storeId]of [['own','company','selected'],['sibling','company','sibling'],['foreign','foreign','foreign'],['corrupt','company','foreign']]){
  insert('ConnectorDevice',{id:'operations88-device-'+id,companyId,storeId,connectorType:id==='foreign'?'RBS_CAPDRIVER':'RBS_READONLY_OBSERVER',deviceName:id==='foreign'||id==='corrupt'?privateText:'Native Observer '+id,version:'native-test',status:'ONLINE',lastSeenAt:at,observerMode:'READ_ONLY',healthJson:{token:privateText}});
  insert('ConnectorEvent',{id:'operations88-event-'+id,connectorDeviceId:'operations88-device-'+id,eventType:'PROTOCOL_OBSERVED',direction:'OUTBOUND',payloadHash:'a'.repeat(64),success:false,errorText:privateText,eventKey:'operations88-key-'+id,source:'CAPDRIVER',byteLength:12,messageType:'CAPDRIVER_COMMAND_OBSERVED',observedAt:at,createdAt:at});
 }
 insert('ProviderConnection',{id:'operations88-provider-own',companyId:'company',providerName:'Native provider',environment:'SANDBOX',status:'DISCONNECTED',webhookSecretRef:privateText});
 for(const [id,companyId,storeId]of [['own','company','selected'],['foreign','foreign','foreign'],['corrupt','company','foreign']]){
  insert('DispatchNote',{id:'operations88-note-'+id,companyId,storeId,documentNumber:'NATIVE88-'+id,recipientName:id==='own'?'Native recipient':privateText,destinationAddress:id==='own'?'Native address':privateText,purpose:'Native transfer',createdByUserId:'admin',createdAt:at});
  insert('DispatchNoteLine',{id:'operations88-line-'+id,dispatchNoteId:'operations88-note-'+id,description:id==='own'?'Native line':privateText,quantity:2,unit:'PIECE'});
  insert('ProviderOutbox',{id:'operations88-outbox-'+id,companyId,aggregateType:'DISPATCH_NOTE',aggregateId:'operations88-note-'+id,action:'ISSUE',idempotencyKey:'operations88-business-key-'+id,payloadHash:'b'.repeat(64),payloadJson:{secret:privateText},lastError:privateText,providerPdfUrl:privateText,createdAt:at});
 }
 insert('DispatchNoteLine',{id:'operations88-line-foreign-product',dispatchNoteId:'operations88-note-own',productId:'party74-product-foreign',description:'Historical own line with unavailable product',quantity:1,unit:'PIECE'});
 return rows.map(entry=>({...entry,json:entry.table==='ConnectorDevice'?['healthJson']:entry.table==='ProviderOutbox'?['payloadJson']:[]}));
}

export async function verifyNativeCompanyOperations({db,profile,revision,secret}){
 const keys=['JWT_SECRET','MWS_STORE_LIFECYCLE_PROFILE','RENDER_GIT_COMMIT','BACKUP_MONITOR_SECRET'],saved=Object.fromEntries(keys.map(k=>[k,process.env[k]]));
 Object.assign(process.env,{JWT_SECRET:'isolated-native-operations-secret',MWS_STORE_LIFECYCLE_PROFILE:`BACKOFFICE_COMPANY_${profile}_V1`,RENDER_GIT_COMMIT:revision,BACKUP_MONITOR_SECRET:secret});
 const mutate=(sql,...values)=>db.$transaction(async tx=>{await tx.$queryRawUnsafe("SELECT set_config('mws.lifecycle_generations',$1,true)",JSON.stringify({selected:'7',sibling:'0',foreign:'0'}));return tx.$executeRawUnsafe(sql,...values)});let server;
 try{
  await mutate('INSERT INTO "CompanyModule"("id","companyId","moduleKey","active") VALUES(\'operations88-module\',\'company\',\'CONNECTOR_RBS\',true) ON CONFLICT ("companyId","moduleKey") DO UPDATE SET "active"=true');
  await mutate('UPDATE "CompanyModule" SET "active"=true WHERE "companyId"=\'company\' AND "moduleKey"=\'INVENTORY\'');
  for(const {table,row,json=[]}of nativeCompanyOperationsSeedPlan()){const entries=Object.entries(row);await mutate(`INSERT INTO "${table}"(${entries.map(([key])=>'"'+key+'"').join(',')}) VALUES(${entries.map(([key],i)=>'$'+(i+1)+(json.includes(key)?'::jsonb':'')).join(',')})`,...entries.map(([key,value])=>json.includes(key)?JSON.stringify(value):value))}
  const owner={id:'company-owner',companyId:'company',role:'OWNER',tokenType:'BACKOFFICE_USER',sessionId:'company-owner-session',sessionVersion:0},caps=[...observerLogisticsActions.map(action=>action.key),'stores.read'];
  for(const cap of ['observer-status.read','observer-events.read','dispatch-notes.read'])await assert.rejects(createStaffAccount(db,owner,{username:'operations88.rejected',fullName:'Rejected',pin:'987654',grants:[],companyCapabilities:[cap]}),{name:'ZodError'});
  const created=await createStaffAccount(db,owner,{username:'company.operations.native',fullName:'Company Operations Native',pin:'987654',grants:[],companyCapabilities:caps});
  await mutate('INSERT INTO "UserSession"("id","userId","expiresAt") VALUES(\'operations88-session\',$1,NOW()+INTERVAL \'1 hour\')',created.id);
  assert.equal((await db.$queryRawUnsafe('SELECT 1 FROM "BackofficeStaffGrant" WHERE "userId"=$1',created.id)).length,0);
  let afterRead=null;const readDb=new Proxy(db,{get(target,key){const value=target[key];if(['$executeRaw','$executeRawUnsafe','$transaction'].includes(key))return()=>assert.fail('operations read cannot write or create a transaction');if(key==='$queryRaw'||key==='$queryRawUnsafe')return async(...args)=>{const sql=typeof args[0]==='string'?args[0]:args[0].sql??args[0].join('?');assert.doesNotMatch(sql,/\b(?:INSERT|UPDATE|DELETE|CREATE|ALTER|FOR UPDATE)\b/i);const result=await value.apply(target,args);if(afterRead&&/FROM "(?:ConnectorDevice|DispatchNote|ProviderOutbox)"/.test(sql)){const action=afterRead;afterRead=null;await action()}return result};if(value&&typeof value==='object'&&!String(key).startsWith('$'))return new Proxy(value,{get(model,method){assert.ok(['findMany','findFirst','findUnique','count'].includes(method),'no model writer');return model[method].bind(model)}});return typeof value==='function'?value.bind(target):value}});
  const authSource=await readFile(new URL('../../src/middleware/auth.js',import.meta.url),'utf8'),actualAuth=new Function('prisma','jwt','assertCustomerDemoRuntimeClosed','enforceBackofficeStaff',authSource.slice(authSource.indexOf('export async function auth(')).replace('export async function auth','async function auth')+';return auth;')(readDb,jwt,assertCustomerDemoRuntimeClosed,enforceBackofficeStaff);let authCalls=0;const auth=(...args)=>{authCalls++;return actualAuth(...args)};
  const app=express();app.use(express.json());app.use('/api/backoffice-staff',createBackofficeStaffRouter({db:readDb,authenticate:auth,issueSession:()=>assert.fail('no session issuer'),repository:{}}));app.use(auth);app.use((_req,res)=>res.status(404).json({code:'UNEXPECTED_FALLTHROUGH'}));app.use((error,_req,res,_next)=>res.status(error.status||500).json({code:error.code}));server=app.listen(0,'127.0.0.1');await new Promise(resolve=>server.once('listening',resolve));
  const token=jwt.sign({id:created.id,companyId:'company',role:'EMPLOYEE',tokenType:'BACKOFFICE_USER',staffAccess:true,sessionVersion:0,sessionId:'operations88-session'},process.env.JWT_SECRET),prefix=observerLogisticsPrefix;
  const get=async(path,{method='GET',headers={}}={})=>{const before=authCalls,r=await fetch(`http://127.0.0.1:${server.address().port}${path}`,{method,headers:{authorization:'Bearer '+token,'x-backoffice-company-id':'company',...headers}}),body=await r.json();assert.equal(authCalls-before,1,'actual authentication exactly once');return{status:r.status,body}};
  const paths={'connector-store-options.read':'/stores','observer-status.read':'/observer-status?storeId=selected','observer-events.read':'/observer-events?storeId=selected&source=CAPDRIVER','logistics-readiness.read':'/readiness','dispatch-notes.read':'/dispatch-notes?storeId=selected','provider-outbox.read':'/outbox'},results={};
  for(const [cap,path]of Object.entries(paths)){const r=await get(prefix+path);assert.equal(r.status,200,JSON.stringify({cap,...r}));assert.equal(r.body.scope,'COMPANY');assert.doesNotMatch(JSON.stringify(r.body),/OPERATIONS88_PRIVATE_CANARY|operations88-event-foreign|operations88-device-corrupt/);results[cap]=r.body}
  const status=results['observer-status.read'];assert.ok(status.items.some(row=>row.id==='operations88-device-own'));assert.equal(status.items.find(row=>row.id==='operations88-device-own').eventCount,1);assert.equal(status.capabilities.fiscalConfirmation,false);assert.equal(Object.hasOwn(status.items[0],'healthJson'),false);
  const events=results['observer-events.read'];assert.ok(events.items.some(row=>row.id==='operations88-event-own'));assert.equal(events.fiscalConfirmation,false);assert.equal(Object.hasOwn(events.items[0],'errorText'),false);assert.equal(Object.hasOwn(events.items[0],'eventKey'),false);
  const readiness=await readProviderReadiness('company',{},null,{db:readDb});assert.equal(results['logistics-readiness.read'].pendingDocuments,readiness.pendingDocuments);assert.equal(results['logistics-readiness.read'].externalTransmissionEnabled,false);
  const nativeNotes=await readDispatchNotes('company',{storeId:'selected'},null,{db:readDb});assert.equal(results['dispatch-notes.read'].items.find(row=>row.id==='operations88-note-own').totalQuantity,Number(nativeNotes.find(row=>row.id==='operations88-note-own').totalQuantity));
  const detail=await get(prefix+'/dispatch-notes/operations88-note-own');assert.equal(detail.status,200);assert.equal(detail.body.items.length,2);assert.equal(detail.body.items.find(row=>row.id==='operations88-line-foreign-product').productId,null);assert.equal(detail.body.items.find(row=>row.id==='operations88-line-foreign-product').sku,null);assert.equal(Object.hasOwn(detail.body.note,'createdByUserId'),false);
  const corruptOutbox=results['provider-outbox.read'].items.find(row=>row.id==='operations88-outbox-corrupt');assert.equal(corruptOutbox.documentNumber,null);assert.equal(corruptOutbox.recipientName,null);
  for(const path of ['/observer-status?storeId=foreign','/observer-events?storeId=foreign','/dispatch-notes/operations88-note-foreign','/dispatch-notes/operations88-note-corrupt'])assert.equal((await get(prefix+path)).status,404);
  for(const path of ['/api/connector-observer/status?storeId=selected','/api/logistics/provider-readiness','/api/logistics/dispatch-notes'])assert.equal((await get(path)).status,403,'no legacy prefix authority');
  assert.equal((await get(prefix+'/readiness',{method:'POST'})).status,403);assert.equal((await get(prefix+'/readiness',{headers:{'x-backoffice-store-id':'selected'}})).status,403);
  for(const module of ['CONNECTOR_RBS','INVENTORY']){await mutate('UPDATE "CompanyModule" SET "active"=false WHERE "companyId"=\'company\' AND "moduleKey"=$1',module);for(const action of observerLogisticsActions){const r=await get(prefix+paths[action.key]);assert.equal(r.status,action.module===module?403:200,JSON.stringify({module,cap:action.key,...r}))}await mutate('UPDATE "CompanyModule" SET "active"=true WHERE "companyId"=\'company\' AND "moduleKey"=$1',module)}
  await mutate('UPDATE "Company" SET "licenseStatus"=\'EXPIRED\' WHERE "id"=\'company\'');for(const path of Object.values(paths))assert.equal((await get(prefix+path)).status,403);await mutate('UPDATE "Company" SET "licenseStatus"=\'ACTIVE\' WHERE "id"=\'company\'');
  afterRead=()=>mutate('UPDATE "CompanyModule" SET "active"=false WHERE "companyId"=\'company\' AND "moduleKey"=\'CONNECTOR_RBS\'');assert.equal((await get(prefix+paths['observer-status.read'])).status,403);await mutate('UPDATE "CompanyModule" SET "active"=true WHERE "companyId"=\'company\' AND "moduleKey"=\'CONNECTOR_RBS\'');
  afterRead=()=>mutate('UPDATE "BackofficeStaffAccount" SET "revision"="revision"+1 WHERE "userId"=$1',created.id);assert.equal((await get(prefix+paths['provider-outbox.read'])).status,403,'fresh revision withholds result');
 }finally{if(server){server.closeAllConnections();await new Promise(resolve=>server.close(resolve))}for(const key of keys){if(saved[key]===undefined)delete process.env[key];else process.env[key]=saved[key]}}
}
